     * surrounding text. So existing text-xs / text-xl classes still size it.
     * The box is an inline style, not a stylesheet rule, because these
     * partials render in every layout, and Tailwind's preflight would
     * otherwise make the svg display:block.
     */
    public static function svg(string $name, string $class = '', array $attributes = []): string
    {
        if (! isset(self::ICONS[$name])) {
            throw new InvalidArgumentException("Unknown icon [{$name}].");
        }

        [$width, $path] = self::ICONS[$name];

        $attributes = array_merge([
            'class' => trim('pm-icon '.$class),
            'width' => round($width / 512, 4).'em',
            'height' => '1em',
            'viewBox' => "0 0 {$width} 512",
            'fill' => 'currentColor',
            'style' => 'display:inline-block;vertical-align:-0.125em;overflow:visible',
            'aria-hidden' => 'true',
            'focusable' => 'false',
        ], $attributes);

        $html = '';
        foreach ($attributes as $key => $value) {
            $html .= ' '.$key.'="'.e($value).'"';
        }

        return '<svg xmlns="http://www.w3.org/2000/svg"'.$html.'><path d="'.$path.'"/></svg>';
    }
}
